const YEAR_MAP = { one: 1, two: 2, three: 3, four: 4, five: 5 };

// Build the index once
function buildCourseIndex(data) {
  const index = new Map();

  for (const [yearKey, semesters] of Object.entries(data)) {
    const year = YEAR_MAP[yearKey.replace("year_", "")];

    for (const [semesterKey, courses] of Object.entries(semesters)) {
      const semester = semesterKey.replace("_semester", ""); // "harmattan" | "rain"

      for (const { code, title } of courses) {
        index.set(normalize(code), { code, title, year, semester });
      }
    }
  }
  return index;
}

// Case/whitespace-insensitive: "csc305", "CSC 305", " csc  305 " all match
function normalize(code) {
  return code.toUpperCase().replace(/\s+/g, "").trim();
}

// Usage
const courseIndex = buildCourseIndex(COURSES_DATA);

function findCourse(code) {
  return courseIndex.get(normalize(code)) ?? null;
}